    const href = a.href;
    if (href.includes('/marketplace/bar-services/') || href.endsWith('/marketplace/')) continue;
    if (!uniqueUrls.has(href)) {
      // Find enclosing card or text
      let p = a;
      while (p && p !== document.body && !p.textContent.includes('Stars') && !p.textContent.includes('Location:')) {
        p = p.parentElement;
      }
      uniqueUrls.set(href, {
        href,
        text: (p ? p.innerText : a.innerText).split('\n').filter(Boolean).slice(0, 10)
      });
    }
  }
  return Array.from(uniqueUrls.values());
});

