const soupTabId = 2052873260;
await tool.wait_for({ tabId: soupTabId, condition: "load_state", value: "load" });

const recipeData = await browserjs(soupTabId, () => {
  // Let's look for recipe title, ingredients, and instructions
  const title = document.querySelector('h1, .wprm-recipe-name')?.innerText?.trim();
  const ingredients = Array.from(document.querySelectorAll('.wprm-recipe-ingredient, [class*="ingredient"]'))
    .map(el => el.innerText.trim())
    .filter(Boolean);

  const instructions = Array.from(document.querySelectorAll('.wprm-recipe-instruction, [class*="instruction"], [class*="direction"]'))
    .map(el => el.innerText.trim())
    .filter(Boolean);

  return {
    title,
    ingredientsCount: ingredients.length,
    ingredientsSample: ingredients.slice(0, 20),
    instructionsCount: instructions.length,
    instructionsSample: instructions.slice(0, 15)
  };
});

console.log("Recipe data:", JSON.stringify(recipeData, null, 2));

